const verifyLines = `-- name: VerifyLines :many
SELECT item_id, sort_order, code, category, stage, amount, basis, explanation, taxable, rounding
FROM payroll_lines WHERE run_id = $1 AND calc_version = $2
ORDER BY item_id, sort_order
`

type VerifyLinesParams struct {
	RunID       uuid.UUID
	CalcVersion int32
}

type VerifyLinesRow struct {
	ItemID      uuid.UUID
	SortOrder   int16
	Code        string
	Category    string
	Stage       string
	Amount      pgtype.Numeric
	Basis       []byte
	Explanation string
	Taxable     bool
	Rounding    string
}

func (q *Queries) VerifyLines(ctx context.Context, arg VerifyLinesParams) ([]VerifyLinesRow, error) {
	rows, err := q.db.Query(ctx, verifyLines, arg.RunID, arg.CalcVersion)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var items []VerifyLinesRow
	for rows.Next() {
		var i VerifyLinesRow
		if err := rows.Scan(
			&i.ItemID,
			&i.SortOrder,
			&i.Code,
			&i.Category,
			&i.Stage,
			&i.Amount,
			&i.Basis,
			&i.Explanation,
			&i.Taxable,
			&i.Rounding,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

const verifyRunTotals = `-- name: VerifyRunTotals :one

SELECT (coalesce(r.total_gross, 0) = s.gross AND coalesce(r.total_deductions, 0) = s.deductions
        AND coalesce(r.total_net, 0) = s.net)::bool AS totals_equal,
       (coalesce(r.item_ok_count, 0) + coalesce(r.item_error_count, 0) + coalesce(r.item_excluded_count, 0) = s.items
        AND s.items = coalesce(r.eligible_count, -1))::bool AS counts_equal,
       s.items::int AS items, coalesce(r.eligible_count, 0)::int AS eligible
FROM payroll_runs r,
     LATERAL (SELECT count(*) AS items,
                     coalesce(sum(gross) FILTER (WHERE status = 'OK'), 0) AS gross,
                     coalesce(sum(deductions) FILTER (WHERE status = 'OK'), 0) AS deductions,
                     coalesce(sum(net) FILTER (WHERE status = 'OK'), 0) AS net
              FROM payroll_items i WHERE i.run_id = r.id AND i.calc_version = r.calc_version) s
WHERE r.id = $1
`

type VerifyRunTotalsRow struct {
	TotalsEqual bool
	CountsEqual bool
	Items       int32
	Eligible    int32
}

// ---------------------------------------------------------------- verify-run (S5, PI-12, ADR-P07)
// PI-05 (verify-run + job payroll.verify_run): total run = Σ item OK versi terkini dan satu item per
// karyawan eligible. Trigger payroll_runs_totals_check menjaganya saat menulis; ini memeriksa data yang
// sudah tersimpan (manipulasi langsung, bug trigger, restore).
func (q *Queries) VerifyRunTotals(ctx context.Context, id uuid.UUID) (VerifyRunTotalsRow, error) {
	row := q.db.QueryRow(ctx, verifyRunTotals, id)
	var i VerifyRunTotalsRow
	err := row.Scan(
		&i.TotalsEqual,
		&i.CountsEqual,
		&i.Items,
		&i.Eligible,
	)
	return i, err
}
